  return{source:text,mode,target,concepts:selected.map(x=>x.id),coreBehavior:primary.behaviors[Math.floor(hash(text)%primary.behaviors.length)],coreEmotion:primary.emotion,feeling:primary.feeling,intensity,keyPhrase:selected[0].phrase||words(text)[0]||primary.label,keywords:words(text),exaggeration:primary.behaviors[(hash(text)+1)%primary.behaviors.length]}
