function blueprint(profile,metaphor,r,rare){const primary=CONCEPTS[profile.concepts[0]],secondary=CONCEPTS[profile.concepts[1]],shapePool=[...primary.shapes,...(secondary?.shapes||[]),"asym","cluster","frame","spiral"];return{coreShape:choose(shapePool,r),coreCount:rare==="BOSS"?range([3,5],r):range([1,3],r),width:+(.72+r()*.62).toFixed(2),height:+(.7+r()*.7).toFixed(2),symmetry:choose(["balanced","offset","lopsided","stacked"],r),facePlacement:choose(["center","high","low","split","side"],r),headCount:profile.concepts.includes("hypocrisy")?2:rare==="BOSS"?range([2,4],r):r()>.78?2:1,limbs:profile.concepts.includes("control")?range([6,10],r):choose([0,2,4,6],r),locomotion:choose(["feet","wheels","hover","tendrils","hops"],r),material:choose(["metal","paper","neon","shadow","organic","glitch"],r),anchorParts:[...new Set([...metaphor.parts,...(secondary?choose(secondary.metaphors,r).parts.slice(0,2):[])])],scale:rare==="BOSS"?1.3:+(.78+r()*.35).toFixed(2),motion:choose(["jitter","swagger","hover","stomp","wave","flicker"],r)} }
