function create(profile,index=0,familiarity={}){const seed=hash(`${profile.source}|${Date.now()}|${Math.random()}|${index}`),r=rng(seed),primary=CONCEPTS[profile.concepts[0]],secondary=CONCEPTS[profile.concepts[1]],metaphor=choose(primary.metaphors,r),rar=rarity(r,profile),bp=blueprint(profile,metaphor,r,rar),palette=choose(PALETTES,r),name=choose(metaphor.names,r),maxHp=range(rarityStats[rar],r),anchor=profile.keyPhrase,oldCount=familiarity[profile.concepts.join("+")]||0;
  const dna={id:`free-${seed.toString(36)}-${index}`,category:profile.concepts.join("+"),sourceType:profile.mode,semanticProfile:profile,semanticAnchor:anchor,represents:`${primary.label}${secondary?`，同时带着${secondary.label}`:""}`,name,rarity:rar,maxHp,hp:maxHp,archetype:"freeform",blueprint:bp,visualTraits:bp.anchorParts,visualExplanation:`用${bp.anchorParts.slice(0,3).join("、")}夸张表现“${profile.coreBehavior}”`,bodyShape:bp.coreShape,bodySize:bp.scale,bodySquishiness:.08,primaryColor:palette[0],secondaryColor:palette[1],accentColor:palette[2],eyes:bp.anchorParts.includes("manyEyes")?range([5,10],r):bp.headCount*choose([1,2],r),eyeExpression:bp.anchorParts.includes("sideEyes")?"side-eye":choose(["glare","wide","squint"],r),mouth:bp.anchorParts.includes("crookedMouth")?"crooked":bp.anchorParts.includes("hugeMouth")?"huge":choose(["grin","frown","square"],r),mouthExpression:profile.coreEmotion,arms:bp.limbs,legs:bp.locomotion==="feet"?choose([2,4,6],r):0,horns:r()>.67,tentacles:bp.locomotion==="tendrils"?range([4,8],r):0,accessory:bp.anchorParts[0],texture:bp.material,aura:rar==="BOSS"?"bossFlames":rar==="RARE"?"pixelHalo":choose(["static","smoke","none"],r),movementStyle:bp.motion,personality:`${profile.coreEmotion}的${profile.coreBehavior}`,arrogance:.5+r()*.48,cowardice:.35+r()*.6,keywords:profile.keywords,intensity:profile.intensity,oldCount,
  idleLines:[oldCount?"又见面了……你怎么还记得我？":null,`${profile.target}：${primary.behaviors[0]}才叫本事。`,profile.concepts[0]==="performative"?"灯光！镜头！都看我！":`关于“${anchor}”，我还能念叨一整晚。`].filter(Boolean),insultLines:[`你连“${anchor}”都摆不平，还想打我？`,"这点伤害也配叫连招？"],lightHitLines:["喂！我的人设像素掉了！","你急什么？我只是说实话。"],mediumHitLines:["等等……我的隐喻结构裂了！",`行了，“${anchor}”也没那么严重！`],panicLines:["你怎么还带连招的？","我可以换一套说法！"],lowHpLines:["别打了！我承认我是在夸张！","HP 要没了，先关音效行不行？"],defeatedLines:["语义成立……但嘴硬模块离线。","我认输！别按终结键！"],surrenderLines:["HP 已归零。"],escapeLines:[],endingStyle:"finisher",phases:rar==="BOSS"?["表象阶段","隐喻暴露","语义崩解"]:[]};
  if(check(profile,dna))return dna;dna.blueprint.anchorParts=[...new Set([...metaphor.parts,...dna.blueprint.anchorParts])];dna.visualExplanation=`${name}直接用${metaphor.parts.slice(0,3).join("、")}表现“${profile.keyPhrase}”`;return dna
}
export function generateMonsters(text,mode="emotion",familiarity={}){const profile=understand(text,mode),overload=/工作.*别人.*未来|未来.*工作|全部.*压|所有.*压/.test(text.replace(/\s+/g,"")),isBoss=(profile.intensity>.82&&profile.concepts.length>=3)||overload,count=isBoss?1:Math.min(3,Math.max(1,profile.concepts.length));const out=[];for(let i=0;i<count;i++){const sub=i===0?profile:{...profile,concepts:[profile.concepts[i],profile.concepts[0]],keyPhrase:CONCEPTS[profile.concepts[i]].label};out.push(create(sub,i,familiarity))}if(isBoss){out[0].rarity="BOSS";out[0].maxHp=range(rarityStats.BOSS,rng(hash(text)));out[0].hp=out[0].maxHp;out[0].blueprint.scale=1.34;out[0].name=choose(["万事压顶总成兽","全域内耗母机","情绪过载终焉体"],rng(hash(text)+4))}return out}
export function analyzeText(text,mode="emotion"){return understand(text,mode).concepts.map((category,i)=>({category,score:3-i*.4,matches:[]}))}
export function getCategoryLabel(category){return category.split("+").map(x=>CONCEPTS[x]?.label||x).join("；")}
